css:
.sl-team-grid {
    position: relative;
    padding-block: clamp(3rem, 6vw, 5rem);
    background-color: var(--smartlearn-bg);
    font-family: var(--smartlearn-body-font, system-ui, sans-serif);
}

.sl-team-grid .sl-mb-16 { margin-bottom: 4rem; }
.sl-team-grid .text-center { text-align: center; }

.sl-team-grid .sl-section-title {
    font-family: var(--smartlearn-heading-font, system-ui, sans-serif);
    font-size: clamp(1.75rem, 3vw, 2.25rem);
    font-weight: 700;
    margin-bottom: 1rem;
    color: var(--smartlearn-text);
}

.sl-team-grid .sl-section-subtitle {
    font-size: 1.125rem;
    color: var(--smartlearn-text-muted);
    max-width: 600px;
    margin: 0 auto;
}

.sl-team-grid .sl-roster-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
    gap: 2rem;
    max-width: 1200px;
    margin: 0 auto;
}

.sl-team-grid .sl-teacher-card {
    background-color: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border, rgba(0, 0, 0, 0.08));
    border-radius: var(--smartlearn-radius, 1rem);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.sl-team-grid .sl-teacher-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
}

.sl-team-grid .sl-teacher-img-wrap {
    width: 100%;
    aspect-ratio: 4 / 3;
    overflow: hidden;
    background-color: color-mix(in srgb, var(--smartlearn-text) 6%, transparent);
}

.sl-team-grid .sl-teacher-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center top;
    transition: transform 0.5s ease;
}

.sl-team-grid .sl-teacher-card:hover .sl-teacher-img {
    transform: scale(1.05);
}

.sl-team-grid .sl-teacher-content {
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.sl-team-grid .sl-teacher-name {
    font-family: var(--smartlearn-heading-font, system-ui, sans-serif);
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--smartlearn-text);
    margin-bottom: 0.25rem;
}

.sl-team-grid .sl-teacher-role {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--smartlearn-primary);
    margin-bottom: 1rem;
}

.sl-team-grid .sl-teacher-bio {
    font-size: 0.9375rem;
    color: var(--smartlearn-text-muted);
    margin-bottom: 1.5rem;
    line-height: 1.5;
    flex-grow: 1;
}

.sl-team-grid .sl-teacher-expertise {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-bottom: 1.5rem;
}

.sl-team-grid .sl-expertise-badge {
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.25rem 0.65rem;
    border-radius: 9999px;
    background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent);
    color: var(--smartlearn-text);
    border: 1px solid color-mix(in srgb, var(--smartlearn-primary) 25%, transparent);
}

.sl-team-grid .sl-teacher-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    margin-top: auto;
    padding-top: 1.5rem;
    border-top: 1px solid var(--smartlearn-card-border, rgba(0, 0, 0, 0.08));
}

.sl-team-grid .sl-teacher-socials {
    display: flex;
    gap: 0.25rem;
}

.sl-team-grid .sl-teacher-socials a {
    color: var(--smartlearn-text-muted);
    transition: color 0.2s ease, background-color 0.2s ease;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 36px;
    min-height: 36px;
    border-radius: var(--smartlearn-radius, 0.5rem);
    text-decoration: none;
}

.sl-team-grid .sl-teacher-socials a:hover {
    color: var(--smartlearn-primary);
    background-color: color-mix(in srgb, var(--smartlearn-text) 8%, transparent);
}

.sl-team-grid .sl-teacher-socials a:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}

.sl-team-grid .sl-btn {
    font-size: 0.875rem;
    font-weight: 600;
    padding: 0.5rem 1rem;
    border-radius: var(--smartlearn-radius, 0.5rem);
    text-decoration: none;
    transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease;
    white-space: nowrap;
}

.sl-team-grid .sl-btn:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}

.sl-team-grid .sl-btn-outline {
    background-color: transparent;
    border: 1px solid var(--smartlearn-card-border, rgba(0, 0, 0, 0.2));
    color: var(--smartlearn-text);
}

.sl-team-grid .sl-btn-outline:hover {
    border-color: var(--smartlearn-text);
    background-color: color-mix(in srgb, var(--smartlearn-text) 8%, transparent);
}

.sl-team-grid .sl-btn-primary {
    background-color: var(--smartlearn-btn-bg);
    border: 1px solid var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text, #ffffff);
}

.sl-team-grid .sl-btn-primary:hover {
    background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg));
    border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg));
}

@media (prefers-reduced-motion: reduce) {
    .sl-team-grid .sl-teacher-card,
    .sl-team-grid .sl-teacher-img,
    .sl-team-grid .sl-teacher-socials a,
    .sl-team-grid .sl-btn {
        transition: none;
    }
    .sl-team-grid .sl-teacher-card:hover,
    .sl-team-grid .sl-teacher-card:hover .sl-teacher-img {
        transform: none;
    }
}
